\label{thm:main} For every fixed \(\beta>0\), as \(r\to+\infty\),
\begin{equation}\label{eq:main}
\mathfrak h_\beta\left(r\right)
=
\left\{
\begin{array}{ll}
-\displaystyle\frac{1}{\pi^2\beta r^2}
+o\left(r^{-2}\right),
&0<\beta<2,\\[8pt]
\displaystyle\frac{\cos\left(2\pi r\right)-1}{2\pi^2r^2},
&\beta=2,\\[8pt]
\displaystyle
\frac{2\Gamma\left(1+2/\beta\right)^2}{\left(2\pi\right)^{4/\beta}}
\frac{\cos\left(2\pi r\right)}{r^{4/\beta}}
+o\left(r^{-4/\beta}\right),
&\beta>2.
\end{array}
\right.
\end{equation}

\label{prop:real-asymptotics}
For real $a>1$, the limit
\begin{equation}\label{eq:amplitude-definition}
\mathfrak U\left(a\right)\overset{\mathrm{def}}{=}
t_1\left(a\right)\lim_{x\to\infty}
\mathrm{e}^{-\mathrm i x}x^{2/a}
\left(
\mathfrak q_1\left(x;a\right)-\frac{\mathrm i\left(a+1\right)}{ax}
\right)
\end{equation}
exists. For each fixed real $a>0$ with $a\ne1$, as $x\to\infty$,
\begin{equation}\label{eq:real-asymptotics}
\mathcal R_a\left(x\right)=
\begin{cases}
1-\dfrac{2}{ax^2}+o\left(x^{-2}\right),&0<a<1,\\[4pt]
1+2\Re\left(\mathfrak U\left(a\right)\mathrm{e}^{\mathrm i x}\right)x^{-2/a}
+o\left(x^{-2/a}\right),&a>1.
\end{cases}
\end{equation}

\label{lem:amplitude-continuation}
The function $\psi_0(a)\mathfrak U(a)$, initially defined for real
$a>1$ by Proposition~\ref{prop:real-asymptotics}, extends holomorphically
to $\Omega=\{a\in\mathbb C:\Re a>1\}$. For some constants $C>0$ and
$M\in\mathbb N$, its extension satisfies
\begin{equation}\label{eq:amplitude-growth}
 \left|\psi_0\left(a\right)\mathfrak U\left(a\right)\right|
 \le C\left(1+\left|a\right|\right)^M,
 \qquad \Re a>3.
\end{equation}
